int handle_sio_cgstampns_ioctl(struct net *net, struct socket *sock, unsigned int cmd, void __user *up) {
    int err;
    struct timespec ts;
    mm_segment_t old_fs;

    old_fs = get_fs();
    set_fs(KERNEL_DS);
    err = sock_do_ioctl(net, sock, cmd, (unsigned long)&ts);
    set_fs(old_fs);
    if (err)
        return err;
    return compat_put_timespec(&ts, up);
}

